INSERT INTO conversations_data (data, cat, lvl, name, ctx) VALUES
  ('{"avi": "👩", "name": "Ji-yeon & Soo-jin", "ctx": "Planning dinner together", "cat": "everyday", "lvl": "b", "catLabel": "Everyday", "msgs": [{"s": "l", "who": "Ji-yeon", "txt": "오늘 저녁에 시간 돼?"}, {"s": "r", "who": "Soo-jin", "txt": "응! 왜? 무슨 일 있어?"}, {"s": "l", "who": "Ji-yeon", "txt": "그냥 같이 밥 먹을 사람 찾는 중 ㅋㅋ"}, {"s": "r", "who": "Soo-jin", "txt": "ㅋㅋ 좋아! 어디서 먹을까?"}, {"s": "l", "who": "Ji-yeon", "txt": "학교 앞 국밥집 어때? 요즘 거기 자주 가거든."}, {"s": "r", "who": "Soo-jin", "txt": "오 국밥 좋지. 몇 시에?"}, {"s": "l", "who": "Ji-yeon", "txt": "6시 반쯤 괜찮아?"}, {"s": "r", "who": "Soo-jin", "txt": "응 완전 좋아 👍"}], "vocab": [{"ko": "시간 돼?", "rom": "sigan dwae?", "en": "Do you have time? / Are you free?"}, {"ko": "무슨 일", "rom": "museun il", "en": "What\\''s up / What\\''s the matter"}, {"ko": "찾는 중", "rom": "channeun jung", "en": "In the middle of looking for"}, {"ko": "학교 앞", "rom": "hakgyo ap", "en": "In front of school"}, {"ko": "자주", "rom": "jaju", "en": "Often / Frequently"}, {"ko": "완전", "rom": "wanjeon", "en": "Totally / Completely (slang)"}], "grammar": [], "mission": []}', 'everyday', 'b', 'Ji-yeon & Soo-jin', 'Planning dinner together'),
  ('{"avi": "👨‍💼", "name": "Team Chat", "ctx": "Asking for a deadline extension", "cat": "work", "lvl": "i", "catLabel": "Workplace", "msgs": [{"s": "l", "who": "Min-su", "txt": "보고서 마감이 오늘인데 조금 더 시간이 필요해요."}, {"s": "r", "who": "Team lead", "txt": "얼마나 더 필요해요?"}, {"s": "l", "who": "Min-su", "txt": "내일 오전까지 가능할까요?"}, {"s": "r", "who": "Team lead", "txt": "이유가 뭐예요?"}, {"s": "l", "who": "Min-su", "txt": "데이터 분석 부분이 예상보다 복잡하게 나왔어요."}, {"s": "r", "who": "Team lead", "txt": "알겠어요. 내일 점심 전까지 주세요."}, {"s": "l", "who": "Min-su", "txt": "감사합니다. 최대한 빨리 드릴게요."}], "vocab": [{"ko": "마감", "rom": "magam", "en": "Deadline"}, {"ko": "가능할까요?", "rom": "ganeunghalkkayo?", "en": "Would it be possible?"}, {"ko": "데이터 분석", "rom": "deiteo bunsek", "en": "Data analysis"}, {"ko": "예상보다", "rom": "yesangboda", "en": "More than expected"}, {"ko": "복잡하다", "rom": "bokjaphada", "en": "To be complicated"}, {"ko": "최대한", "rom": "choedaehan", "en": "As much as possible / To the maximum"}], "grammar": [], "mission": []}', 'work', 'i', 'Team Chat', 'Asking for a deadline extension'),
  ('{"avi": "👫", "name": "Couple Chat", "ctx": "Making up after an argument", "cat": "dating", "lvl": "i", "catLabel": "Dating", "msgs": [{"s": "l", "who": "Hyun", "txt": "아까 내가 좀 심했던 것 같아. 미안해."}, {"s": "r", "who": "Ji", "txt": "나도 과민반응했어. 괜찮아."}, {"s": "l", "who": "Hyun", "txt": "오늘 저녁에 우리 같이 밥 먹을까?"}, {"s": "r", "who": "Ji", "txt": "응, 어디 갈까?"}, {"s": "l", "who": "Hyun", "txt": "네가 좋아하는 데로 가자. 내가 살게."}, {"s": "r", "who": "Ji", "txt": "ㅎㅎ 그럼 파스타 먹고 싶어."}], "vocab": [{"ko": "심하다", "rom": "simhada", "en": "To be harsh / extreme / too much"}, {"ko": "과민반응", "rom": "gwamin ban-eung", "en": "Overreaction"}, {"ko": "네가 좋아하는 데", "rom": "nega joahaneun de", "en": "The place you like"}, {"ko": "내가 살게", "rom": "naega salge", "en": "I\\''ll pay / It\\''s on me"}], "grammar": [], "mission": []}', 'dating', 'i', 'Couple Chat', 'Making up after an argument'),
  ('{"avi": "🧑‍🤝‍🧑", "name": "Min-jun & Tae-yang", "ctx": "Weekend plans", "cat": "friends", "lvl": "b", "catLabel": "Friends", "msgs": [{"s": "l", "who": "Min-jun", "txt": "이번 주말에 뭐 해?"}, {"s": "r", "who": "Tae-yang", "txt": "아직 계획 없어. 왜?"}, {"s": "l", "who": "Min-jun", "txt": "영화 보러 갈래? 새로 나온 거 재밌대."}, {"s": "r", "who": "Tae-yang", "txt": "무슨 영화?"}, {"s": "l", "who": "Min-jun", "txt": "액션 영화인데 평점이 되게 높아."}, {"s": "r", "who": "Tae-yang", "txt": "좋아, 몇 시 어때?"}, {"s": "l", "who": "Min-jun", "txt": "2시 어때? 그러면 밥도 같이 먹을 수 있어."}], "vocab": [{"ko": "이번 주말", "rom": "ibeon jumal", "en": "This weekend"}, {"ko": "새로 나온", "rom": "saero naon", "en": "Newly released"}, {"ko": "재밌대", "rom": "jaemitdae", "en": "They say it\\''s fun (hearsay)"}, {"ko": "평점", "rom": "pyeongjeom", "en": "Rating / Score"}, {"ko": "되게", "rom": "doege", "en": "Really / Very (colloquial)"}], "grammar": [], "mission": []}', 'friends', 'b', 'Min-jun & Tae-yang', 'Weekend plans'),
  ('{"avi": "👨‍👩‍👧", "name": "Family Group Chat", "ctx": "Mom asking about dinner", "cat": "family", "lvl": "b", "catLabel": "Family", "msgs": [{"s": "l", "who": "Mom", "txt": "오늘 저녁 집에서 먹을 거야?"}, {"s": "r", "who": "Da-eun", "txt": "응, 몇 시에 먹어요?"}, {"s": "l", "who": "Mom", "txt": "6시 반쯤. 좋아하는 거 만들어줄게."}, {"s": "r", "who": "Da-eun", "txt": "된장찌개 해주세요!"}, {"s": "l", "who": "Mom", "txt": "ㅎㅎ 알겠어. 일찍 들어와."}], "vocab": [{"ko": "집에서 먹다", "rom": "jibeseo meokda", "en": "To eat at home"}, {"ko": "~쯤", "rom": "~jjeum", "en": "Around / About (approximate time)"}, {"ko": "만들어줄게", "rom": "mandeureo julge", "en": "I\\''ll make (it) for you"}, {"ko": "된장찌개", "rom": "doenjang jjigae", "en": "Fermented soybean paste stew"}, {"ko": "일찍", "rom": "iljjik", "en": "Early"}], "grammar": [], "mission": []}', 'family', 'b', 'Family Group Chat', 'Mom asking about dinner'),
  ('{"avi": "💼", "name": "Interview Prep", "ctx": "Job interview Q&A", "cat": "work", "lvl": "a", "catLabel": "Workplace", "msgs": [{"s": "l", "who": "Interviewer", "txt": "지원 동기가 무엇인지 말씀해 주시겠어요?"}, {"s": "r", "who": "Applicant", "txt": "저는 귀사의 혁신적인 문화에 매력을 느꼈습니다."}, {"s": "l", "who": "Interviewer", "txt": "구체적인 사례를 들어 설명해 주실 수 있나요?"}, {"s": "r", "who": "Applicant", "txt": "네, 최근 출시하신 AI 서비스가 특히 인상적이었습니다."}, {"s": "l", "who": "Interviewer", "txt": "본인의 강점이 이 직무에 어떻게 기여할 것 같으신가요?"}, {"s": "r", "who": "Applicant", "txt": "저는 데이터 기반 의사결정과 팀 협업에 강점이 있습니다."}], "vocab": [{"ko": "지원 동기", "rom": "jiwon donggi", "en": "Motivation for applying"}, {"ko": "귀사", "rom": "gwisa", "en": "Your company (formal/respectful)"}, {"ko": "혁신적", "rom": "hyeoksinjeok", "en": "Innovative"}, {"ko": "구체적인 사례", "rom": "guchejeokin sarye", "en": "Specific example/case"}, {"ko": "기여하다", "rom": "giyeohada", "en": "To contribute"}, {"ko": "의사결정", "rom": "uisagyeoljeong", "en": "Decision-making"}], "grammar": [], "mission": []}', 'work', 'a', 'Interview Prep', 'Job interview Q&A'),
  ('{"avi": "🛒", "name": "At the Convenience Store", "ctx": "Buying snacks", "cat": "everyday", "lvl": "b", "catLabel": "Everyday", "msgs": [{"s": "l", "who": "Cashier", "txt": "봉투 필요하세요?"}, {"s": "r", "who": "Customer", "txt": "아니요, 괜찮아요. 카드로 계산할게요."}, {"s": "l", "who": "Cashier", "txt": "영수증 드릴까요?"}, {"s": "r", "who": "Customer", "txt": "아니요, 됐어요."}, {"s": "l", "who": "Cashier", "txt": "3,500원입니다. 감사합니다."}], "vocab": [{"ko": "봉투", "rom": "bongtu", "en": "(Shopping) bag"}, {"ko": "카드로 계산", "rom": "kadeu-ro gyesan", "en": "Pay by card"}, {"ko": "영수증", "rom": "yeongsujeung", "en": "Receipt"}, {"ko": "됐어요", "rom": "dwaesseoyo", "en": "It\\''s fine / No need (dismissive OK)"}], "grammar": [], "mission": []}', 'everyday', 'b', 'At the Convenience Store', 'Buying snacks'),
  ('{"avi": "🎤", "name": "After Norebang", "ctx": "Deciding where to go next", "cat": "friends", "lvl": "i", "catLabel": "Friends", "msgs": [{"s": "l", "who": "Ha-na", "txt": "노래방 끝났는데 이제 어디 갈까?"}, {"s": "r", "who": "Joon", "txt": "배고프지 않아? 삼겹살 어때?"}, {"s": "l", "who": "Ha-na", "txt": "좋아! 근처에 24시간 하는 데 있잖아."}, {"s": "r", "who": "Joon", "txt": "맞아, 거기 진짜 맛있더라."}, {"s": "l", "who": "Ha-na", "txt": "그럼 빨리 가자. 배 너무 고파."}], "vocab": [{"ko": "노래방", "rom": "noraebang", "en": "Karaoke room / Singing room"}, {"ko": "삼겹살", "rom": "samgyeopsal", "en": "Grilled pork belly"}, {"ko": "근처", "rom": "geuncheo", "en": "Nearby / In the vicinity"}, {"ko": "24시간", "rom": "isipsa sigan", "en": "24 hours / Open 24/7"}, {"ko": "진짜 맛있더라", "rom": "jinjja masitdeora", "en": "It was really delicious (recalled experience)"}], "grammar": [], "mission": []}', 'friends', 'i', 'After Norebang', 'Deciding where to go next'),
  ('{"avi": "💌", "name": "First Date Plans", "ctx": "Deciding on a place", "cat": "dating", "lvl": "i", "catLabel": "Dating", "msgs": [{"s": "l", "who": "Se-jun", "txt": "이번 주말에 같이 뭐 할까요?"}, {"s": "r", "who": "Ye-jin", "txt": "한강 피크닉 어때요? 날씨가 좋을 것 같아요."}, {"s": "l", "who": "Se-jun", "txt": "좋아요! 제가 김밥 싸올게요 ㅎㅎ"}, {"s": "r", "who": "Ye-jin", "txt": "오 진짜요? 저는 음료 가져올게요."}, {"s": "l", "who": "Se-jun", "txt": "몇 시에 만날까요?"}, {"s": "r", "who": "Ye-jin", "txt": "오후 2시 어때요? 한강공원 입구에서요."}], "vocab": [{"ko": "피크닉", "rom": "pikeunik", "en": "Picnic"}, {"ko": "날씨가 좋을 것 같다", "rom": "nalssiga joheul geot gatda", "en": "The weather looks like it\\''ll be nice"}, {"ko": "싸올게요", "rom": "ssaolgeyo", "en": "I\\''ll pack and bring (food)"}, {"ko": "음료", "rom": "eumnyo", "en": "Drink / Beverage"}, {"ko": "입구", "rom": "ipgu", "en": "Entrance"}], "grammar": [], "mission": []}', 'dating', 'i', 'First Date Plans', 'Deciding on a place'),
  ('{"avi": "🏠", "name": "With Parents", "ctx": "Coming home late", "cat": "family", "lvl": "i", "catLabel": "Family", "msgs": [{"s": "l", "who": "Mom", "txt": "오늘 몇 시에 들어와?"}, {"s": "r", "who": "Son", "txt": "친구들이랑 저녁 먹고 들어갈게요. 좀 늦을 것 같아요."}, {"s": "l", "who": "Mom", "txt": "밥은 먹었어? 너무 늦지 않게 들어와."}, {"s": "r", "who": "Son", "txt": "네, 먹었어요. 11시 전에 들어갈게요."}, {"s": "l", "who": "Mom", "txt": "알겠어. 조심해서 들어와."}], "vocab": [{"ko": "들어오다/가다", "rom": "deureooda/gada", "en": "To come/go inside (return home)"}, {"ko": "늦을 것 같다", "rom": "neujeul geot gatda", "en": "It seems like it\\''ll be late"}, {"ko": "너무 늦지 않게", "rom": "neomu neutji ange", "en": "Not too late"}, {"ko": "조심하다", "rom": "josimhada", "en": "To be careful / Take care"}], "grammar": [], "mission": []}', 'family', 'i', 'With Parents', 'Coming home late'),
  ('{"avi": "🏥", "name": "At the Pharmacy", "ctx": "Getting medicine for a cold", "cat": "everyday", "lvl": "i", "catLabel": "Everyday", "msgs": [{"s": "l", "who": "Pharmacist", "txt": "어디가 불편하세요?"}, {"s": "r", "who": "Customer", "txt": "목이 아프고 콧물이 나요. 열도 조금 있어요."}, {"s": "l", "who": "Pharmacist", "txt": "감기약 드릴게요. 하루에 세 번 식후에 드세요."}, {"s": "r", "who": "Customer", "txt": "얼마나 먹어야 나아요?"}, {"s": "l", "who": "Pharmacist", "txt": "3일치 드릴게요. 충분히 쉬시는 게 중요해요."}], "vocab": [{"ko": "어디가 불편하세요?", "rom": "eodie bulpyeonhaseyo?", "en": "Where does it hurt? / What\\''s bothering you?"}, {"ko": "콧물이 나다", "rom": "konmuri nada", "en": "To have a runny nose"}, {"ko": "식후", "rom": "sikhu", "en": "After a meal"}, {"ko": "나아요", "rom": "naayo", "en": "Get better / Recover"}, {"ko": "충분히", "rom": "chungbunhi", "en": "Sufficiently / Enough"}], "grammar": [], "mission": []}', 'everyday', 'i', 'At the Pharmacy', 'Getting medicine for a cold'),
  ('{"avi": "📊", "name": "Before the Meeting", "ctx": "Checking if ready", "cat": "work", "lvl": "i", "catLabel": "Workplace", "msgs": [{"s": "l", "who": "Manager", "txt": "회의 준비 다 됐어요?"}, {"s": "r", "who": "Staff", "txt": "네, 자료는 다 준비했는데 프린터가 안 돼서요."}, {"s": "l", "who": "Manager", "txt": "그냥 화면으로 보여줘요. 어차피 다 노트북 있잖아요."}, {"s": "r", "who": "Staff", "txt": "아, 그렇게 하면 되겠네요. 감사합니다."}, {"s": "l", "who": "Manager", "txt": "5분 후에 회의실로 오세요."}], "vocab": [{"ko": "준비 다 됐어요?", "rom": "junbi da dwaesseoyo?", "en": "Are you all ready? / Is everything prepared?"}, {"ko": "자료", "rom": "jaryo", "en": "Materials / Documents / Data"}, {"ko": "어차피", "rom": "eochapi", "en": "Anyway / Either way"}, {"ko": "회의실", "rom": "hoe-uisil", "en": "Meeting room / Conference room"}], "grammar": [], "mission": []}', 'work', 'i', 'Before the Meeting', 'Checking if ready');